#[test]
fn darcys() {
    for v in [1.0, 0.3, -42.75, 1e6, 123456.789] {
        // Generated conversion vs. the upstream formula, verbatim.
        let x: f64 = v;
        let base = x * 9.869233e-13;
        assert_close(
            PorousMediumPermeability::from_darcys(v).as_base(),
            base,
            F64_TOL,
        );
        let x: f64 = base;
        let back = x / 9.869233e-13;
        assert_close(
            PorousMediumPermeability::from_base(base).as_darcys(),
            back,
            F64_TOL,
        );
        assert_close(
            PorousMediumPermeability::from_darcys(v).as_darcys(),
            v,
            ROUND_TRIP_TOL,
        );
        // f32 storage.
        assert_close(
            PorousMediumPermeability::from_darcys(v as f32).as_base() as f64,
            base,
            F32_TOL,
        );
        assert_close(
            PorousMediumPermeability::from_base(base as f32).as_darcys() as f64,
            back,
            F32_TOL,
        );
    }
}

