#[test]
fn new_and_convert_to_match_named_methods() {
    let v = 1234.5;
    assert_eq!(
        PorousMediumPermeability::new(v, PorousMediumPermeabilityUnit::Darcy),
        PorousMediumPermeability::from_darcys(v)
    );
    assert_eq!(
        PorousMediumPermeability::from_base(v).convert_to(PorousMediumPermeabilityUnit::Darcy),
        PorousMediumPermeability::from_base(v).as_darcys()
    );
    assert_eq!(
        PorousMediumPermeability::new(v, PorousMediumPermeabilityUnit::Microdarcy),
        PorousMediumPermeability::from_microdarcys(v)
    );
    assert_eq!(
        PorousMediumPermeability::from_base(v).convert_to(PorousMediumPermeabilityUnit::Microdarcy),
        PorousMediumPermeability::from_base(v).as_microdarcys()
    );
    assert_eq!(
        PorousMediumPermeability::new(v, PorousMediumPermeabilityUnit::Millidarcy),
        PorousMediumPermeability::from_millidarcys(v)
    );
    assert_eq!(
        PorousMediumPermeability::from_base(v).convert_to(PorousMediumPermeabilityUnit::Millidarcy),
        PorousMediumPermeability::from_base(v).as_millidarcys()
    );
    assert_eq!(
        PorousMediumPermeability::new(v, PorousMediumPermeabilityUnit::SquareMeter),
        PorousMediumPermeability::from_square_meters(v)
    );
    assert_eq!(
        PorousMediumPermeability::from_base(v)
            .convert_to(PorousMediumPermeabilityUnit::SquareMeter),
        PorousMediumPermeability::from_base(v).as_square_meters()
    );
    assert_eq!(
        PorousMediumPermeability::new(v, PorousMediumPermeabilityUnit::SquareCentimeter),
        PorousMediumPermeability::from_square_centimeters(v)
    );
    assert_eq!(
        PorousMediumPermeability::from_base(v)
            .convert_to(PorousMediumPermeabilityUnit::SquareCentimeter),
        PorousMediumPermeability::from_base(v).as_square_centimeters()
    );
}

#[test]
fn parse_every_abbreviation() {
    assert_eq!(
        "D".parse::<PorousMediumPermeabilityUnit>(),
        Ok(PorousMediumPermeabilityUnit::Darcy)
    );
    assert_eq!(
        format!("2.5 {}", "D").parse::<PorousMediumPermeability>(),
        Ok(PorousMediumPermeability::new(
            2.5,
            PorousMediumPermeabilityUnit::Darcy
        ))
    );
    assert_eq!(
        "µD".parse::<PorousMediumPermeabilityUnit>(),
        Ok(PorousMediumPermeabilityUnit::Microdarcy)
    );
    assert_eq!(
        format!("2.5 {}", "µD").parse::<PorousMediumPermeability>(),
        Ok(PorousMediumPermeability::new(
            2.5,
            PorousMediumPermeabilityUnit::Microdarcy
        ))
    );
    assert_eq!(
        "mD".parse::<PorousMediumPermeabilityUnit>(),
        Ok(PorousMediumPermeabilityUnit::Millidarcy)
    );
    assert_eq!(
        format!("2.5 {}", "mD").parse::<PorousMediumPermeability>(),
        Ok(PorousMediumPermeability::new(
            2.5,
            PorousMediumPermeabilityUnit::Millidarcy
        ))
    );
    assert_eq!(
        "m²".parse::<PorousMediumPermeabilityUnit>(),
        Ok(PorousMediumPermeabilityUnit::SquareMeter)
    );
    assert_eq!(
        format!("2.5 {}", "m²").parse::<PorousMediumPermeability>(),
        Ok(PorousMediumPermeability::new(
            2.5,
            PorousMediumPermeabilityUnit::SquareMeter
        ))
    );
    assert_eq!(
        "cm²".parse::<PorousMediumPermeabilityUnit>(),
        Ok(PorousMediumPermeabilityUnit::SquareCentimeter)
    );
    assert_eq!(
        format!("2.5 {}", "cm²").parse::<PorousMediumPermeability>(),
        Ok(PorousMediumPermeability::new(
            2.5,
            PorousMediumPermeabilityUnit::SquareCentimeter
        ))
    );
    assert_eq!(
        "1 not-a-unit".parse::<PorousMediumPermeability>(),
        Err(ParseError::UnknownUnit)
    );
}

#[test]
fn arithmetic_f64() {
    let a = PorousMediumPermeability::from_base(6.0);
    let b = PorousMediumPermeability::from_base(2.0);
    assert_eq!((a + b).as_base(), 8.0);
    assert_eq!((a - b).as_base(), 4.0);
    assert_eq!((-a).as_base(), -6.0);
    assert_eq!((a * 2.0).as_base(), 12.0);
    assert_eq!((2.0 * a).as_base(), 12.0);
    assert_eq!((a / 2.0).as_base(), 3.0);
    assert_eq!(a / b, 3.0);
    let mut c = a;
    c += b;
    c -= b;
    c *= 2.0;
    c /= 4.0;
    assert_eq!(c.as_base(), 3.0);
}

#[test]
fn arithmetic_integer() {
    let a = PorousMediumPermeability::<i64>::from_base(7);
    let b = PorousMediumPermeability::<i64>::from_base(2);
    assert_eq!(a + b, PorousMediumPermeability::from_base(9));
    assert_eq!(a % b, PorousMediumPermeability::from_base(1));
    assert_eq!(a / b, 3);
    assert!(a > b);
    assert_eq!(
        [a, b].iter().sum::<PorousMediumPermeability<i64>>(),
        PorousMediumPermeability::from_base(9)
    );
}
